#!/bin/sh
# R22 Windows cross-build host-side moduleinfotool bridge (the R21 method:
# the SDK's post-build step invokes the PE moduleinfotool on the Linux host,
# which cannot execute; this wrapper copies the moduleinfo.json generated by
# the IDENTICAL-variant Linux build -- the factory metadata is a compile-time
# property of the same sources with the same defines).
set -e
PATH_ARG=""
OUTPUT_ARG=""
while [ $# -gt 0 ]; do
    case "$1" in
        -path) PATH_ARG="$2"; shift 2 ;;
        -output) OUTPUT_ARG="$2"; shift 2 ;;
        *) shift ;;
    esac
done
[ -z "$PATH_ARG" ] && exit 1
[ -z "$OUTPUT_ARG" ] && exit 1
BUNDLE="$(basename "$PATH_ARG")"
case "$BUNDLE" in
    PitchLab_Lagrange6_Balanced.vst3)  SRC=build_r22 ;;
    PitchLab_Lagrange6_Hybrid.vst3)    SRC=build_vst3_r22_hyb ;;
    PitchLab_ObsKernel6_Balanced.vst3) SRC=build_vst3_r22_obs ;;
    PitchLab_Lagrange6_FullRate.vst3)  SRC=build_vst3_r22_full ;;
    *) echo "moduleinfotool-host: unknown bundle $BUNDLE" >&2; exit 1 ;;
esac
NATIVE=/home/z/my-project/octavox-work/Octavox_RE_evidence/native/vst3
SRCJSON="$NATIVE/$SRC/VST3/Release/$BUNDLE/Contents/Resources/moduleinfo.json"
if [ ! -f "$SRCJSON" ]; then
    echo "moduleinfotool-host: missing source moduleinfo $SRCJSON" >&2
    exit 1
fi
mkdir -p "$(dirname "$OUTPUT_ARG")"
cp "$SRCJSON" "$OUTPUT_ARG"
echo "[R22-host] moduleinfo.json copied for $BUNDLE"
